const names=['กานต์','ข้าวหอม','ต้นกล้า','น้ำใส','ภูผา','พิมพ์','ต้นน้ำ','ไออุ่น','ใบเฟิร์น','นนท์','ออมสิน','ขุนเขา','มะปราง','วิน','สายรุ้ง','ปันปัน','ต้นข้าว','ฟ้าใส','ปุณณ์','พลอย','ตะวัน','มิ้นท์','โบนัส','เจเจ','แก้ม','นับดาว','โอม','พราว','ภูมิ','ชมพู'];
const faces=['🧒🏻','👧🏻','🧑🏻','👧🏽','🧒🏽','👧🏻'];
const dutyGroups=[['พื้นห้องและใต้โต๊ะ','กานต์ · ข้าวหอม · ต้นกล้า','🧹'],['กระดานและหน้าชั้น','น้ำใส · ภูผา · พิมพ์','🧽'],['โต๊ะ เก้าอี้ และทางเดิน','ต้นน้ำ · ไออุ่น · ใบเฟิร์น','🪑'],['ถังขยะและจุดล้างมือ','นนท์ · ออมสิน · ขุนเขา','🗑️'],['ปิดไฟ พัดลม และหน้าต่าง','มะปราง · วิน · สายรุ้ง','💡']];
const defaults={savings:8450,statuses:names.map((_,i)=>i===27?'late':i===28?'leave':i===29?'absent':'present'),duties:dutyGroups.map(()=> 'pending'),scores:names.map((n,i)=>({name:n,score:[68,64,59,55,51,49,47,44,42,40][i]||25+((i*7)%15)})),transactions:[]};
let data=JSON.parse(localStorage.getItem('class62')||'null')||structuredClone(defaults);if(!data.duties)data.duties=dutyGroups.map(()=> 'pending');let modalMode='good';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function persist(){localStorage.setItem('class62',JSON.stringify(data));render()}
function render(){
 const counts={present:0,late:0,leave:0,absent:0};data.statuses.forEach(s=>counts[s]++);
 $('#presentStat').textContent=counts.present+'/30';$('#sumPresent').textContent=counts.present;$('#sumLate').textContent=counts.late;$('#sumLeave').textContent=counts.leave;$('#sumAbsent').textContent=counts.absent;
 const todayScore=data.transactions.filter(x=>x[0]==='✦'||x[0]==='−').reduce((sum,x)=>sum+(x[3]||0),0);$('#goodStat').textContent=(todayScore>=0?'+':'')+todayScore;
 $('#savingStat').textContent='฿'+data.savings.toLocaleString();$('#savingHero').textContent='฿'+data.savings.toLocaleString();
 $('#attendanceList').innerHTML=names.map((n,i)=>'<div class="student"><span class="avatar">'+faces[i%faces.length]+'</span><b>'+(i+1)+'. '+n+'</b><button class="status '+data.statuses[i]+'" data-i="'+i+'">'+({present:'มา',late:'สาย',leave:'ลา',absent:'ขาด'}[data.statuses[i]])+'</button></div>').join('');
 $$('.status').forEach(b=>b.onclick=()=>{const seq=['present','late','leave','absent'];data.statuses[b.dataset.i]=seq[(seq.indexOf(data.statuses[b.dataset.i])+1)%4];persist()});
 const dc={done:0,pending:0,fix:0};data.duties.forEach(s=>dc[s]++);$('#dutyDone').textContent=dc.done;$('#dutyPending').textContent=dc.pending;$('#dutyFix').textContent=dc.fix;$('#dutyStat').textContent=dc.done+'/'+dutyGroups.length;
 $('#dutyList').innerHTML=dutyGroups.map((g,i)=>'<article class="duty-card '+data.duties[i]+'"><span class="duty-icon">'+g[2]+'</span><div><h3>'+g[0]+'</h3><p>'+g[1]+'</p></div><button class="duty-status '+data.duties[i]+'" data-i="'+i+'">'+({pending:'รอตรวจ',done:'เรียบร้อย',fix:'ต้องแก้ไข'}[data.duties[i]])+'</button></article>').join('');
 $$('.duty-status').forEach(b=>b.onclick=()=>{const seq=['pending','done','fix'];data.duties[b.dataset.i]=seq[(seq.indexOf(data.duties[b.dataset.i])+1)%3];persist()});
 const leaders=[...data.scores].sort((a,b)=>b.score-a.score);$('#leaderboard').innerHTML=leaders.map((x,i)=>'<div class="leader"><b>'+(i+1)+'</b><span class="avatar">'+faces[i%faces.length]+'</span><span>'+x.name+'</span><strong>'+x.score+' คะแนน</strong></div>').join('');
 $('#stars').innerHTML=leaders.slice(0,3).map((x,i)=>'<div class="star"><span class="avatar">'+faces[i]+'</span><b>'+x.name+'</b><small>'+x.score+' คะแนน</small><span class="medal">'+['อันดับ 1','พัฒนาดี','สม่ำเสมอ'][i]+'</span></div>').join('');
 $('#savers').innerHTML=leaders.slice(2,9).map((x,i)=>'<div class="saver"><span class="avatar">'+faces[(i+2)%6]+'</span><b>'+x.name+'</b><strong>'+(4-i%2)+' สัปดาห์</strong></div>').join('');
 const base=[['✦',leaders[0].name+' ได้รับ +5 คะแนน จากการช่วยเพื่อน','10 นาทีที่แล้ว'],['฿','ข้าวหอม ออมเงินเพิ่ม ฿20','35 นาทีที่แล้ว'],['✓','เช็คชื่อวันนี้เรียบร้อยแล้ว','08:15 น.']];
 $('#feed').innerHTML=[...data.transactions.slice(-2).reverse(),...base].slice(0,4).map(x=>'<div class="feed-item"><span>'+x[0]+'</span><p>'+x[1]+'<br><small>'+x[2]+'</small></p></div>').join('')
}
$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view).classList.add('active');$('#pageTitle').textContent={dashboard:'สวัสดีตอนเช้า ห้อง ป.6/2',attendance:'เช็คชื่อประจำวัน',duty:'เช็คการทำเวร',goodness:'คะแนนพฤติกรรม',saving:'บันทึกการออม'}[b.dataset.view]});
const reasons={good:['ช่วยเหลือเพื่อน','รับผิดชอบหน้าที่','ตั้งใจเรียน','มีน้ำใจแบ่งปัน','ดูแลห้องเรียน'],deduct:['ไม่ส่งงาน','รบกวนการเรียน','ไม่รับผิดชอบเวร','มาสาย','ผิดข้อตกลงของห้อง']};
function openModal(mode){modalMode=mode;const save=mode==='saving',deduct=mode==='deduct';$('#modalKicker').textContent=save?'บันทึกการออม':'คะแนนพฤติกรรม';$('#modalTitle').textContent=save?'บันทึกเงินออม':deduct?'หักคะแนน':'เพิ่มคะแนน';$('#amountLabel').childNodes[0].textContent=save?'จำนวนเงิน (บาท)':'จำนวนคะแนน';$('#reasonWrap').style.display=save?'none':'grid';if(!save)$('#reasonSelect').innerHTML=reasons[mode].map(x=>'<option>'+x+'</option>').join('');$('#amountInput').value=save?20:5;$('#saveModal').className=deduct?'danger full':'primary full';$('#modal').showModal()}
$('#studentSelect').innerHTML=names.map((n,i)=>'<option value="'+i+'">'+n+'</option>').join('');
$('#addGood').onclick=()=>openModal('good');$('#deductGood').onclick=()=>openModal('deduct');$('#addSaving').onclick=()=>openModal('saving');
$('#saveModal').onclick=e=>{e.preventDefault();const i=+$('#studentSelect').value,amount=Math.max(1,+$('#amountInput').value||1);if(modalMode==='good'){data.scores[i].score+=amount;data.transactions.push(['✦',names[i]+' ได้รับ +'+amount+' คะแนน: '+$('#reasonSelect').value,'เมื่อสักครู่',amount])}else if(modalMode==='deduct'){data.scores[i].score-=amount;data.transactions.push(['−',names[i]+' ถูกหัก '+amount+' คะแนน: '+$('#reasonSelect').value,'เมื่อสักครู่',-amount])}else{data.savings+=amount;data.transactions.push(['฿',names[i]+' ออมเงินเพิ่ม ฿'+amount,'เมื่อสักครู่',0])}persist();$('#modal').close();toast('บันทึกเรียบร้อยแล้ว')};
$('#allPresent').onclick=()=>{data.statuses=data.statuses.map(()=> 'present');persist();toast('เช็คชื่อว่ามาครบทุกคนแล้ว')};$('#allDutyDone').onclick=()=>{data.duties=data.duties.map(()=> 'done');persist();toast('บันทึกว่าเวรเรียบร้อยทุกจุดแล้ว')};$('#resetBtn').onclick=()=>{data=structuredClone(defaults);persist();toast('เริ่มข้อมูลตัวอย่างใหม่แล้ว')};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),1800)}
$('#dateLine').textContent=new Intl.DateTimeFormat('th-TH',{dateStyle:'full'}).format(new Date());render();